public class InnerCallAnalyticsCategoryInterruptionFilterFactory(Action<Humidifier.Transcribe.CallAnalyticsCategoryTypes.InterruptionFilter> factoryAction = null) : SubResourceFactory<Humidifier.Transcribe.CallAnalyticsCategoryTypes.InterruptionFilter>
{

    internal InnerCallAnalyticsCategoryRelativeTimeRangeFactory RelativeTimeRangeFactory { get; set; }

    internal InnerCallAnalyticsCategoryAbsoluteTimeRangeFactory AbsoluteTimeRangeFactory { get; set; }

    protected override Humidifier.Transcribe.CallAnalyticsCategoryTypes.InterruptionFilter Create()
    {
        var interruptionFilterResult = CreateInterruptionFilter();
        factoryAction?.Invoke(interruptionFilterResult);

        return interruptionFilterResult;
    }

    private Humidifier.Transcribe.CallAnalyticsCategoryTypes.InterruptionFilter CreateInterruptionFilter()
    {
        var interruptionFilterResult = new Humidifier.Transcribe.CallAnalyticsCategoryTypes.InterruptionFilter();

        return interruptionFilterResult;
    }
    public override void CreateChildren(Humidifier.Transcribe.CallAnalyticsCategoryTypes.InterruptionFilter result)
    {
        base.CreateChildren(result);

        result.RelativeTimeRange ??= RelativeTimeRangeFactory?.Build();
        result.AbsoluteTimeRange ??= AbsoluteTimeRangeFactory?.Build();
    }

} // End Of Class

